def encode_frame(payload):
    if len(payload) > 65535:
        raise ValueError("Length of payload must be less than or equal to 65535")
    return payload.encode("utf-8")[:2] + payload.encode("utf-8")[2:]

def wait_microseconds(start, end):
    if not isinstance(start, datetime) or not isinstance(end, datetime):
        raise ValueError("start and end must be datetime objects")
    if start > end:
        raise ValueError("start must be before end")
    if start.tzinfo != end.tzinfo:
        raise ValueError("start and end must have the same timezone")
    delta = end - start
    if delta.days > 0:
        raise ValueError("multi-day spans are not supported")
    return delta.microseconds

def capture_append(target):
    with open(target, 'a') as file:
        try:
            while True:
                yield file.write(input("Enter text to append: "))
        except Exception as e:
            file.truncate(0)
            raise e

def find_matches(records, columns, needle):
    import re
    needle = needle.lower()
    matches = []
    for record in records:
        for column in columns:
            if isinstance(record[column], str):
                if re.search(needle, record[column], re.IGNORECASE):
                    matches.append(record)
                    break
    return matches

def pad_rows(rows, width, fill=None):
    if width < 0:
        raise ValueError("width must be non-negative")
    for row in rows:
        if len(row) < width:
            row.extend([fill] * (width - len(row)))
        yield row
